import { useEffect } from "react";

const JapReminder = () => {
  useEffect(() => {
    const checkReminder = () => {
      const now = new Date();
      if (now.getHours() === 6 && now.getMinutes() === 0) {
        alert("📿 Jap time thai gayo 🙏");
      }
    };

    const interval = setInterval(checkReminder, 60000);
    return () => clearInterval(interval);
  }, []);

  return null;
};


export default JapReminder;
